// Base CSV parser interface and utilities for credit card and bank transaction parsing

import type { ParsedTransaction, CSVParseResult } from '$lib/models/Transaction';

/**
 * Base interface for all CSV parsers
 */
export interface ICSVParser {
	/**
	 * Parse a CSV string and return transactions
	 * @param csvContent The raw CSV file content as a string
	 * @returns CSVParseResult with parsed transactions and any errors
	 */
	parse(csvContent: string): CSVParseResult;

	/**
	 * Validate if the CSV format matches this parser's expected format
	 * @param csvContent The raw CSV file content as a string
	 * @returns true if the format matches, false otherwise
	 */
	validateFormat(csvContent: string): boolean;
}

/**
 * Base CSV parser with common utility methods
 */
export abstract class BaseCSVParser implements ICSVParser {
	abstract parse(csvContent: string): CSVParseResult;
	abstract validateFormat(csvContent: string): boolean;

	/**
	 * Parse CSV string into rows and columns
	 * Handles quoted fields with commas
	 */
	protected parseCSV(csvContent: string): string[][] {
		const lines = csvContent.split(/\r?\n/);
		const result: string[][] = [];

		// Strip a surviving surrounding "..." pair from a finalized field.
		// EQ Bank exports double-encoded values like `"""-$33.00"""`, which the
		// standard unwrap above reduces to `"-$33.00"` (literal " still present).
		const stripOuterQuotes = (field: string): string => {
			const trimmed = field.trim();
			if (trimmed.length >= 2 && trimmed.startsWith('"') && trimmed.endsWith('"')) {
				return trimmed.slice(1, -1).trim();
			}
			return trimmed;
		};

		for (const line of lines) {
			if (!line.trim()) continue;

			const row: string[] = [];
			let currentField = '';
			let inQuotes = false;

			for (let i = 0; i < line.length; i++) {
				const char = line[i];

				if (char === '"') {
					// Handle escaped quotes
					if (inQuotes && line[i + 1] === '"') {
						currentField += '"';
						i++; // Skip next quote
					} else {
						inQuotes = !inQuotes;
					}
				} else if (char === ',' && !inQuotes) {
					row.push(stripOuterQuotes(currentField));
					currentField = '';
				} else {
					currentField += char;
				}
			}

			// Add the last field
			row.push(stripOuterQuotes(currentField));
			result.push(row);
		}

		return result;
	}

	/**
	 * Parse a date string in MM/DD/YYYY or YYYY-MM-DD format to YYYY-MM-DD
	 */
	protected parseDate(dateStr: string): string | null {
		try {
			// Remove any leading/trailing whitespace
			dateStr = dateStr.trim();

			// Try YYYY-MM-DD format (new EQ Bank format)
			const ymdMatch = dateStr.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
			if (ymdMatch) {
				const [, year, month, day] = ymdMatch;
				return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
			}

			// Try MM/DD/YYYY format
			const mdyMatch = dateStr.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
			if (mdyMatch) {
				const [, month, day, year] = mdyMatch;
				return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
			}

			// Try DD MMM YYYY format (e.g., "31 May 2025" or "31-May-25")
			const dmmyMatch = dateStr.match(/^(\d{1,2})[\s\-]([A-Za-z]{3})[\.\s\-]*(\d{2,4})$/);
			if (dmmyMatch) {
				const [, day, monthStr, year] = dmmyMatch;
				const monthMap: Record<string, string> = {
					jan: '01',
					feb: '02',
					mar: '03',
					apr: '04',
					may: '05',
					jun: '06',
					jul: '07',
					aug: '08',
					sep: '09',
					oct: '10',
					nov: '11',
					dec: '12'
				};
				const month = monthMap[monthStr.toLowerCase()];
				if (month) {
					const fullYear = year.length === 2 ? `20${year}` : year;
					return `${fullYear}-${month}-${day.padStart(2, '0')}`;
				}
			}

			// Try DD Mon YYYY format with full month name
			const dmonyMatch = dateStr.match(/^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})$/);
			if (dmonyMatch) {
				const [, day, monthStr, year] = dmonyMatch;
				const monthMap: Record<string, string> = {
					january: '01',
					february: '02',
					march: '03',
					april: '04',
					may: '05',
					june: '06',
					july: '07',
					august: '08',
					september: '09',
					october: '10',
					november: '11',
					december: '12'
				};
				const month = monthMap[monthStr.toLowerCase()];
				if (month) {
					return `${year}-${month}-${day.padStart(2, '0')}`;
				}
			}

			return null;
		} catch {
			return null;
		}
	}

	/**
	 * Parse amount from string, handling currency symbols, commas, and parentheses for negatives
	 */
	protected parseAmount(amountStr: string): number | null {
		try {
			// Trim whitespace and any surrounding quote characters left over from
			// double-encoded CSV exports (e.g. EQ Bank emits `"""-$33.00"""` which
			// unwraps once to a value still containing literal " characters).
			amountStr = amountStr.trim().replace(/^["']+|["']+$/g, '').trim();

			// Check if amount is in parentheses (negative)
			const isNegative = amountStr.startsWith('(') && amountStr.endsWith(')');
			if (isNegative) {
				amountStr = amountStr.slice(1, -1);
			}

			// Remove currency symbols, commas, whitespace, and any embedded quotes
			amountStr = amountStr.replace(/[$,\s"']/g, '');

			// Parse the number
			const amount = parseFloat(amountStr);
			if (isNaN(amount)) return null;

			return isNegative ? -Math.abs(amount) : amount;
		} catch {
			return null;
		}
	}

	/**
	 * Remove BOM (Byte Order Mark) if present
	 */
	protected removeBOM(content: string): string {
		if (content.charCodeAt(0) === 0xfeff) {
			return content.slice(1);
		}
		return content;
	}

	/**
	 * Check if a header row contains expected columns (case-insensitive)
	 */
	protected hasExpectedColumns(header: string[], expectedColumns: string[]): boolean {
		const headerLower = header.map((h) => h.toLowerCase().trim());
		return expectedColumns.every((col) => headerLower.includes(col.toLowerCase()));
	}

	/**
	 * Normalizes transaction amounts to positive values for expenses.
	 *
	 * For user-friendly display, expenses should be positive and refunds/credits should be negative.
	 * Different banks use different conventions:
	 * - PC Financial, EQ Bank, RBC, TD Bank, Simplii, Wealth Simple: Use negative for expenses → Need inversion
	 * - American Express: Already uses positive for expenses → No inversion needed
	 *
	 * @param amount - The parsed amount from CSV
	 * @param invertSign - If true, inverts the sign (for banks using negative for expenses). Default: true
	 * @returns Normalized amount (positive = expense, negative = refund/credit) or null if input is null
	 *
	 * @example
	 * // PC Financial: -50.00 (expense) → keep as-is
	 * normalizeAmount(-50.00, false) // Returns -50.00
	 *
	 * @example
	 * // American Express: 50.00 (expense) → invert to -50.00
	 * normalizeAmount(50.00, true) // Returns -50.00
	 *
	 * @example
	 * // PC Financial: 25.00 (refund) → keep as-is
	 * normalizeAmount(25.00, false) // Returns 25.00
	 *
	 * Specification: #{#trn1b}
	 */
	protected normalizeAmount(amount: number | null, invertSign: boolean = true): number | null {
		if (amount === null || amount === undefined) return null;
		if (amount === 0) return 0;

		return invertSign ? amount * -1 : amount;
	}
}

