6	import { BaseCSVParser } from './BaseCSVParser';
7	import type { CSVParseResult, ParsedTransaction } from '$lib/models/Transaction';
8	
9	export class AmexParser extends BaseCSVParser {
10		parse(csvContent: string): CSVParseResult {
11			const transactions: ParsedTransaction[] = [];
12			const errors: string[] = [];
13	
14			try {
15				csvContent = this.removeBOM(csvContent);
16				const rows = this.parseCSV(csvContent);
17	
18				if (rows.length < 2) {
19					errors.push('CSV file is empty or has no data rows');
20					return { transactions, errors };
21				}
22	
23				// Find the data header row (contains "Date,Date Processed,Description,Amount")
24				let headerRowIdx = -1;
25				for (let i = 0; i < rows.length; i++) {
26					const row = rows[i];
27					if (
28						row.some((cell) => cell.toLowerCase() === 'date') &&
29						row.some((cell) => cell.toLowerCase().includes('description')) &&
30						row.some((cell) => cell.toLowerCase() === 'amount')
31					) {
32						headerRowIdx = i;
33						break;
34					}
35				}
36	
37				if (headerRowIdx === -1) {
38					errors.push(
39						'Invalid American Express CSV format. Could not find header row with Date, Description, and Amount columns'
40					);
41					return { transactions, errors };
42				}
43	
44				const header = rows[headerRowIdx];
45				const dateIdx = header.findIndex((h) => h.toLowerCase() === 'date');
46				const descriptionIdx = header.findIndex((h) => h.toLowerCase() === 'description');
47				const amountIdx = header.findIndex((h) => h.toLowerCase() === 'amount');
48	
49				if (dateIdx === -1 || descriptionIdx === -1 || amountIdx === -1) {
50					errors.push('Could not find required columns in header row');
51					return { transactions, errors };
52				}
53	
54				// Parse data rows (start after header)
55				for (let i = headerRowIdx + 1; i < rows.length; i++) {
56					const row = rows[i];
57					if (row.length < 3) continue; // Skip incomplete rows
58	
59					const dateStr = row[dateIdx]?.trim();
60					const description = row[descriptionIdx]?.trim();
61					const amountStr = row[amountIdx]?.trim();
62	
63					// Skip empty rows
64					if (!dateStr && !description && !amountStr) continue;
65	
66					// Parse date
67					const transaction_date = this.parseDate(dateStr);
68					if (!transaction_date) {
69						errors.push(`Row ${i + 1}: Invalid date format "${dateStr}"`);
70						continue;
71					}
72	
73					// Parse amount
74					const rawAmount = this.parseAmount(amountStr);
75					if (rawAmount === null) {
76						errors.push(`Row ${i + 1}: Invalid amount "${amountStr}"`);
77						continue;
78					}
79	
80					// American Express uses positive for expenses — invert to negative (#{#trn2c})
81					const amount = this.normalizeAmount(rawAmount, true);
82	
83					// Validate description
84					if (!description) {
85						errors.push(`Row ${i + 1}: Missing vendor name/description`);
86						continue;
87					}
88	
89					transactions.push({
90						transaction_date,
91						vendor_name: description,
92						amount
93					});
94				}
95			} catch (e: any) {
96				errors.push(`Failed to parse CSV: ${e.message || 'Unknown error'}`);
97			}
98	
99			return { transactions, errors };
100		}
101	
102		validateFormat(csvContent: string): boolean {
103			try {
104				csvContent = this.removeBOM(csvContent);
105				const rows = this.parseCSV(csvContent);
106				if (rows.length === 0) return false;
107	
108				// Look for American Express identifying features:
109				// 1. Early rows contain "American Express" text
110				// 2. Has a data header row with Date, Description, Amount
111				const hasAmexIdentifier = rows
112					.slice(0, 5)
113					.some((row) => row.some((cell) => cell.toLowerCase().includes('american express')));
114	
115				const hasDataHeader = rows.some(
116					(row) =>
117						row.some((cell) => cell.toLowerCase() === 'date') &&
118						row.some((cell) => cell.toLowerCase() === 'description') &&
119						row.some((cell) => cell.toLowerCase() === 'amount')
120				);
121	
122				return hasAmexIdentifier && hasDataHeader;
123			} catch {
124				return false;
125			}
126		}
127	}
