			// Find the data header row (contains "Date,Date Processed,Description,Amount")
			let headerRowIdx = -1;
			for (let i = 0; i < rows.length; i++) {
				const row = rows[i];
				if (
					row.some((cell) => cell.toLowerCase() === 'date') &&
					row.some((cell) => cell.toLowerCase().includes('description')) &&
					row.some((cell) => cell.toLowerCase() === 'amount')
				) {
					headerRowIdx = i;
					break;
				}
			}

