			}

			const header = rows[headerRowIdx];
			const dateIdx = header.findIndex((h) => h.toLowerCase() === 'date');
			const descriptionIdx = header.findIndex((h) => h.toLowerCase() === 'description');
			const amountIdx = header.findIndex((h) => h.toLowerCase() === 'amount');

			if (dateIdx === -1 || descriptionIdx === -1 || amountIdx === -1) {
				errors.push('Could not find required columns in header row');
				return { transactions, errors };
			}

