			for (let i = headerRowIdx + 1; i < rows.length; i++) {
				const row = rows[i];
				if (row.length < 3) continue; // Skip incomplete rows

				const dateStr = row[dateIdx]?.trim();
				const description = row[descriptionIdx]?.trim();
				const amountStr = row[amountIdx]?.trim();

				// Skip empty rows
				if (!dateStr && !description && !amountStr) continue;

				// Parse date
				const transaction_date = this.parseDate(dateStr);
				if (!transaction_date) {
					errors.push(`Row ${i + 1}: Invalid date format "${dateStr}"`);
					continue;
				}

				// Parse amount
				const rawAmount = this.parseAmount(amountStr);
				if (rawAmount === null) {
					errors.push(`Row ${i + 1}: Invalid amount "${amountStr}"`);
					continue;
				}

				// American Express uses positive for expenses — invert to negative (#{#trn2c})
				const amount = this.normalizeAmount(rawAmount, true);

				// Validate description
				if (!description) {
					errors.push(`Row ${i + 1}: Missing vendor name/description`);
					continue;
				}

				transactions.push({
					transaction_date,
					vendor_name: description,
					amount
				});
			}
		} catch (e: any) {
			errors.push(`Failed to parse CSV: ${e.message || 'Unknown error'}`);
		}

		return { transactions, errors };
	}

	validateFormat(csvContent: string): boolean {
		try {
			csvContent = this.removeBOM(csvContent);
			const rows = this.parseCSV(csvContent);
			if (rows.length === 0) return false;

			// Look for American Express identifying features:
			// 1. Early rows contain "American Express" text
			// 2. Has a data header row with Date, Description, Amount
			const hasAmexIdentifier = rows
				.slice(0, 5)
				.some((row) => row.some((cell) => cell.toLowerCase().includes('american express')));

			const hasDataHeader = rows.some(
				(row) =>
					row.some((cell) => cell.toLowerCase() === 'date') &&
					row.some((cell) => cell.toLowerCase() === 'description') &&
					row.some((cell) => cell.toLowerCase() === 'amount')
			);

			return hasAmexIdentifier && hasDataHeader;
		} catch {
			return false;
		}
	}
}

