import { BaseCSVParser } from './BaseCSVParser';
import type { CSVParseResult, ParsedTransaction } from '$lib/models/Transaction';

export class EQBankParser extends BaseCSVParser {
	parse(csvContent: string): CSVParseResult {
		const transactions: ParsedTransaction[] = [];
		const errors: string[] = [];

		try {
			csvContent = this.removeBOM(csvContent);
			const rows = this.parseCSV(csvContent);

			if (rows.length < 2) {
				errors.push('CSV file is empty or has no data rows');
