			if (!this.validateFormat(csvContent)) {
				errors.push('Invalid EQ Bank CSV format. Expected columns: Date, Description, Amount');
				return { transactions, errors };
			}

			// Find column indices
			const dateIdx = header.findIndex(
				(h) => h.toLowerCase().includes('date') || h.toLowerCase() === 'transfer date'
			);
			const descriptionIdx = header.findIndex((h) => h.toLowerCase().includes('description'));
			const amountIdx = header.findIndex((h) => h.toLowerCase().includes('amount'));

			if (dateIdx === -1 || descriptionIdx === -1 || amountIdx === -1) {
				errors.push('Could not find required columns in CSV header');
				return { transactions, errors };
			}

			// Parse data rows
			for (let i = 1; i < rows.length; i++) {
				const row = rows[i];
				if (row.length < 3) continue; // Skip incomplete rows

				const dateStr = row[dateIdx]?.trim();
				const description = row[descriptionIdx]?.trim();
				const amountStr = row[amountIdx]?.trim();

				// Skip empty rows
				if (!dateStr && !description && !amountStr) continue;

				// Parse date
				const transaction_date = this.parseDate(dateStr);
				if (!transaction_date) {
					errors.push(`Row ${i + 1}: Invalid date format "${dateStr}"`);
					continue;
				}

				// Parse amount (parentheses indicate negative)
				const rawAmount = this.parseAmount(amountStr);
				if (rawAmount === null) {
					errors.push(`Row ${i + 1}: Invalid amount "${amountStr}"`);
					continue;
				}

