				});
			}
		} catch (e: any) {
			errors.push(`Failed to parse CSV: ${e.message || 'Unknown error'}`);
		}

		return { transactions, errors };
	}

	validateFormat(csvContent: string): boolean {
		try {
			csvContent = this.removeBOM(csvContent);
			const rows = this.parseCSV(csvContent);
			if (rows.length === 0) return false;

			const header = rows[0];
			// Check for EQ Bank-specific columns
			// Must have exactly 3 or 4 columns
			if (header.length < 3 || header.length > 4) return false;

